    14      const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    15      if (stored === "light" || stored === "dark") return stored;
    16      return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    17    } catch (_) {
    18      return "light";
    19    }
